<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Avaliações de clientes | ShopVivaliz</title><meta name="description" content="Veja avaliações publicadas de clientes e compartilhe sua experiência real com a ShopVivaliz."><link rel="stylesheet" href="/css/style.css"><link rel="stylesheet" href="/css/footer-pages.css?v=20260728-3"><style>.review-form{max-width:720px;margin:0 auto}.review-form label{display:block;font-weight:800;color:#173b63;margin:14px 0 6px}.review-form input,.review-form select,.review-form textarea{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:10px;padding:12px;font:inherit}.review-form textarea{min-height:150px;resize:vertical}.review-form button{margin-top:16px;border:0;border-radius:10px;padding:12px 18px;background:#0b4f88;color:#fff;font-weight:800}.review-note{font-size:13px;color:#64748b}.hp{position:absolute;left:-9999px}.review-how{margin-top:22px;padding:18px;border-radius:14px;background:#f4f8fc;border:1px solid #dbe5ef}.review-how h2{margin-top:0;color:#0b4f88}.review-how ol{padding-left:20px;line-height:1.7}.review-proof{max-width:960px;margin:0 auto 28px}.review-proof-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.review-card{padding:17px;border:1px solid #dbe5ef;border-radius:14px;background:#fff;box-shadow:0 8px 24px rgba(15,23,42,.05)}.review-stars{color:#d97706;letter-spacing:2px;font-size:18px}.review-card p{color:#334155;line-height:1.55}.review-author{font-weight:800;color:#173b63}.review-verified{display:inline-block;margin-top:8px;padding:4px 8px;border-radius:999px;background:#ecfdf5;color:#047857;font-size:12px;font-weight:800}</style><?php require_once __DIR__.'/includes/head-analytics.php'; ?></head><body>
